};
const q = $input.first().json.query ?? {};
const ok = !!cfg.verifyToken && q["hub.mode"] === "subscribe" && q["hub.verify_token"] === cfg.verifyToken;
return [{ json: { ok, challenge: String(q["hub.challenge"] ?? "") } }];

const __env = (k, d = "") => { try { const v = $env[k]; return v === undefined || v === null || v === "" ? d : String(v); } catch (e) { return d; } };
const cfg = {
  apiUrl: __env("CONVEXA_API_URL", "https://api-convexa.altvia.cloud").replace(/\/+$/, ""),
  graphBase: __env("GRAPH_API_BASE", "https://graph.facebook.com").replace(/\/+$/, ""),
  graphVersion: __env("GRAPH_API_VERSION", "v25.0"),
  verifyToken: __env("WHATSAPP_VERIFY_TOKEN", ""),
  testToken: __env("CONVEXA_TEST_TOKEN", ""),
  exigirAssinatura: __env("CONVEXA_EXIGIR_ASSINATURA", "true") !== "false",
  humanHours: Math.max(Number(__env("CONVEXA_HUMANO_HORAS", "12")) || 12, 0.25),
  reminderHours: Math.max(Number(__env("CONVEXA_LEMBRETE_HORAS", "24")) || 24, 1),
  tplLembrete: __env("CONVEXA_TEMPLATE_LEMBRETE", "convexa_lembrete"),
  tplPos: __env("CONVEXA_TEMPLATE_POS", ""),
  tplLang: __env("CONVEXA_TEMPLATE_IDIOMA", "pt_BR"),
  alertUrl: __env("CONVEXA_ALERTA_WEBHOOK_URL", ""),
  ia: __env("CONVEXA_IA", "auto"),
  wf: {"WF00":"cs1xHHp13UwQIpkR","WF01":"FjGdfMtAM5nAZu4Q","WF02":"rqqKIPjaeAqEy8GW","WF03":"tPmuN5i2mwY8whUh","WF04":"3vGOPsRRUJxxJtqm","WF05":"teeIpYOjy1LeRaHT","WF06":"wHl9gupQNIMgqkid","WF07":"fJByu5qfUoLICkhT","WF08":"o5UVBX2a06p0VBGb","WF09":"cyESqJD5y2H5klTX","WF10":"u5PofWGIegW0fxr1","WF11":"FDRYEf2GO7QqaRU1","WF12":"P5jQ0lMlJKm3n4Z7","WF13":"1iP6wUyAgMECKreB","WF14":"gwRuN7kMLozuUyEf","WF15":"cvxIntegraMeta15","WF16":"cvxRegistros0016","WF17":"cvxInstalacao017"},
};
// Corpo exatamente como chegou (a assinatura da Meta é calculada sobre ele)
const item = $input.first();
let raw = "";
try { if (item.binary?.data) raw = (await this.helpers.getBinaryDataBuffer(0, "data")).toString("utf8"); } catch (e) { raw = ""; }
const h = item.json.headers ?? {};
let body = item.json.body;
if (!raw) raw = JSON.stringify(body ?? {});
if (!body || typeof body !== "object" || !Object.keys(body).length) { try { body = JSON.parse(raw); } catch (e) { body = {}; } }
const meta = body?.object === "whatsapp_business_account" || Array.isArray(body?.entry);
const phoneNumberId = meta ? body.entry?.[0]?.changes?.[0]?.value?.metadata?.phone_number_id ?? null : body.phoneNumberId ?? null;
return [{ json: { acao: "validar", cfg, origem: meta ? "meta" : "teste", rawBody: raw, assinatura: String(h["x-hub-signature-256"] ?? ""), autorizacao: String(h["authorization"] ?? ""), phoneNumberId, body } }];

const j = $input.first().json;
const ok = !!j.cfg.testToken && j.autorizacao === "Bearer " + j.cfg.testToken;
return [{ json: { valida: ok, motivo: ok ? "ok" : j.cfg.testToken ? "token_de_teste_invalido" : "testes_desligados" } }];

const j = $('API Autorizada?').first().json;
const req = $('Ler requisição').first().json;
const textos = { sem_integracao: "O número da Meta não tem integração cadastrada no painel (token da Meta).", sem_app_secret: "A integração da Meta está sem App Secret no painel: não dá para conferir a assinatura dos webhooks.", api_indisponivel: "A ConvexaAPI não respondeu ao conferir a assinatura do webhook." };
return [{ json: { tipo: "WEBHOOK_RECUSADO", mensagem: (textos[j.motivo] ?? j.motivo) + " phoneNumberId=" + (req.phoneNumberId ?? "?"), detalhe: { motivo: j.motivo, phoneNumberId: req.phoneNumberId }, chave: "RECUSA:" + j.motivo + ":" + (req.phoneNumberId ?? "") + ":" + new Date().toISOString().slice(0, 13), origem: "WF00" } }];

// Transforma o evento (Meta ou formato de teste) em uma mensagem por item.
// Ignora status de entrega/leitura, reações e eventos de sistema.
const req = $("Ler requisição").first().json;
const body = req.body ?? {};
const cfg = req.cfg;
const out = [];

// Telefone no formato da API (+55DDNNNNNNNNN). O WhatsApp às vezes entrega celular do Brasil sem o 9.
const paraE164 = (wa) => {
  let d = String(wa ?? "").replace(/\D/g, "");
  if (/^55\d{10}$/.test(d) && /^[6-9]/.test(d.slice(4))) d = d.slice(0, 4) + "9" + d.slice(4);
  return d ? "+" + d : "";
};
const IGNORAR = new Set(["reaction", "system", "request_welcome", "unsupported", "ephemeral", "errors"]);

if (req.origem === "meta") {
  for (const entry of body.entry ?? []) {
    for (const ch of entry.changes ?? []) {
      if (ch.field && ch.field !== "messages") continue;
      const v = ch.value ?? {};
      const pnid = v.metadata?.phone_number_id;
      const contatos = v.contacts ?? [];
      for (const m of v.messages ?? []) {
        if (IGNORAR.has(m.type)) continue;
        const contato = contatos.find((x) => x.wa_id === m.from) ?? (contatos.length === 1 ? contatos[0] : {});
        // Com "usernames" (2026) a Meta pode mandar só o id do usuário, sem telefone. A agenda
        // identifica o cliente pelo telefone, então essas mensagens não têm como ser atendidas.
        const waId = String(m.from ?? contato.wa_id ?? "").replace(/\D/g, "");
        if (!waId) continue;
        let type = "text", text = "", replyId = "", title = "";
        if (m.type === "text") text = m.text?.body ?? "";
        else if (m.type === "interactive") {
          const r = m.interactive?.button_reply ?? m.interactive?.list_reply ?? {};
          type = "reply";
          replyId = r.id ?? "";
          title = r.title ?? "";
        } else if (m.type === "button") {
          type = "reply";
          replyId = m.button?.payload ?? "";
          title = m.button?.text ?? "";
        } else {
          type = "unsupported";
          text = m[m.type]?.caption ?? "";
        }
        out.push({
          json: {
            cfg,
            origem: "meta",
            requestId: `meta-${m.id}`,
            phoneNumberId: String(pnid ?? ""),
            waId,
            phone: paraE164(waId),
            profileName: contato.profile?.name ?? null,
            message: { id: m.id, type, text: String(text).trim().slice(0, 2000), replyId: String(replyId), title: String(title), timestamp: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : new Date().toISOString() },
          },
        });
      }
    }
  }
  out.sort((a, b) => a.json.message.timestamp.localeCompare(b.json.message.timestamp));
} else {
  // Formato simplificado dos nossos testes:
  // { requestId, phoneNumberId, customer: { phone, name }, message: { id, type, text, replyId } }
  const tel = String(body.customer?.phone ?? "").replace(/\D/g, "");
  if (!body.phoneNumberId) throw new Error("phoneNumberId obrigatório");
  if (!tel) throw new Error("Telefone do cliente obrigatório");
  const m = body.message ?? {};
  const replyId = String(m.replyId ?? "");
  if (!replyId && !String(m.text ?? "").trim()) throw new Error("Texto da mensagem obrigatório");
  out.push({
    json: {
      cfg,
      origem: "teste",
      requestId: body.requestId ?? `teste-${Date.now()}`,
      phoneNumberId: String(body.phoneNumberId),
      waId: tel,
      phone: paraE164(tel),
      profileName: body.customer?.name ?? null,
      message: { id: m.id ?? `teste-${Date.now()}`, type: replyId ? "reply" : "text", text: String(m.text ?? "").trim().slice(0, 2000), replyId, title: String(m.title ?? ""), timestamp: new Date().toISOString() },
    },
  });
}
return out;

// Junta a mensagem com o estado salvo da conversa (tabela convexa_conversas).
const m = $("Uma mensagem por vez").first().json;
const linha = $input.first().json ?? {};
let conv = {};
try { conv = linha.conversa ? JSON.parse(linha.conversa) : {}; } catch (e) { conv = {}; }
conv = { mode: "AI", flow: null, step: "IDLE", data: {}, ...conv };

// A Meta reenvia o mesmo evento se não recebeu 200 a tempo: não responde duas vezes
if (linha.lastMessageId && linha.lastMessageId === m.message.id) return [{ json: { ...m, duplicada: true } }];

const agora = Date.now();
const N = (s) => String(s ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
const t = N(m.message.text);
const rid = m.message.replyId ?? "";
const parado = (h) => conv.stepAt && agora - Date.parse(conv.stepAt) > h * 3600e3;
const zerar = () => Object.assign(conv, { step: "IDLE", flow: null, data: {} });

// atendimento humano vence sozinho
if (conv.mode === "HUMAN" && conv.humanUntil && Date.parse(conv.humanUntil) < agora) Object.assign(conv, { mode: "AI", humanUntil: null });

if (conv.mode !== "HUMAN") {
  // conversa abandonada no meio: depois de 2 h recomeça (a resposta ao lembrete vale por 30 h)
  if (conv.step !== "IDLE" && parado(conv.step === "WAITING_APPOINTMENT_CONFIRMATION_REPLY" ? 30 : 2)) zerar();
  // "menu", "sair"... ou um botão do menu: recomeça de qualquer ponto
  if (/^(menu|inicio|voltar|sair|parar|reiniciar|comecar|recomecar|cancelar tudo)$/.test(t) || rid.startsWith("menu:")) zerar();
  // botão de um lembrete antigo: vai para a confirmação mesmo que a conversa tenha mudado
  if (rid.startsWith("lem:") && conv.step !== "WAITING_APPOINTMENT_CONFIRMATION_REPLY") Object.assign(conv, { step: "WAITING_APPOINTMENT_CONFIRMATION_REPLY", flow: "lembrete", data: { appointmentId: rid.split(":")[2] ?? null } });
}

return [{ json: { ...m, duplicada: false, conversation: conv, ultimaEntradaAnterior: linha.lastInboundAt ?? null, replies: [], events: [], alerts: [] } }];

const ctx = $input.first().json;
ctx.replies ??= []; ctx.events ??= []; ctx.alerts ??= [];
return [{ json: ctx }];

// Estado final da conversa: vira a linha da tabela convexa_conversas.
const ctx = $input.first().json;
const conv = ctx.conversation ?? { mode: "AI", step: "IDLE", flow: null, data: {} };
const linha = {
  chave: `${ctx.phoneNumberId}:${ctx.phone}`,
  phoneNumberId: String(ctx.phoneNumberId ?? ""),
  waId: String(ctx.waId ?? ""),
  phone: String(ctx.phone ?? ""),
  nome: String(ctx.session?.customer?.name ?? ctx.profileName ?? ""),
  mode: conv.mode ?? "AI",
  step: conv.step ?? "IDLE",
  conversa: JSON.stringify(conv),
  lastMessageId: String(ctx.message?.id ?? ""),
  lastInboundAt: new Date().toISOString(),
};
return [{ json: linha }];

// Um subworkflow falhou: pede desculpas ao cliente, recomeça a conversa e avisa a equipe (WF14).
const base = $("Montar contexto").first().json;
const erro = $input.first().json ?? {};
const mensagem = String(erro.error?.message ?? erro.error ?? erro.message ?? "erro desconhecido").slice(0, 500);
let sessao = null;
try { sessao = $("Call 'Convexa - 10 Dados do Cliente'").first().json?.session ?? null; } catch (e) { sessao = null; }
return [
  {
    json: {
      ...base,
      session: sessao,
      conversation: { ...base.conversation, step: "IDLE", flow: null, data: {} },
      replies: [{ kind: "text", text: "Desculpe, tive um problema aqui 😕 Pode repetir, por favor? Se preferir, digite *atendente*." }],
      events: [],
      alerts: [{ tipo: "FALHA_NO_FLUXO", mensagem, detalhe: { passo: base.conversation?.step, texto: base.message?.text?.slice(0, 200) }, chave: `FALHA:${base.phoneNumberId}:${new Date().toISOString().slice(0, 13)}`, origem: "WF00" }],
    },
  },
];

const r = $('Resultado').first().json;
const req = $('Ler requisição').first().json;
const simular = r.origem === "teste" && req.body?.enviar !== true;
return [{ json: { acao: "enviar", cfg: r.cfg, origem: r.origem, simular, phoneNumberId: r.phoneNumberId, waId: r.waId, replies: r.replies ?? [] } }];

let r = null;
try { r = $('Resultado').first().json; } catch (e) { r = null; }
if (!r) return [{ json: { success: true, duplicada: true, replies: [] } }];
return [{ json: { success: true, replies: r.replies ?? [], conversation: { mode: r.conversation?.mode, flow: r.conversation?.flow, step: r.conversation?.step }, events: r.events ?? [], alerts: (r.alerts ?? []).map((a) => a.tipo) } }];
